// --- OPTIMIZACIONES EXTRA INYECTADAS ---
// Limitar FPS y liberar memoria al desmontar
if (typeof window !== 'undefined') {
  const originalRAF = window.requestAnimationFrame;
  let lastT = 0;
  window.requestAnimationFrame = (cb) => originalRAF((t)=>{
    if (t - lastT < 14) return originalRAF(cb); // ~70fps cap para ahorrar bateria
    lastT = t;
    cb(t);
  });
}
